+        try {
+            String stateKey = storedRulesFile.getCanonicalPath();
+            storeState = STORES_BY_PATH.computeIfAbsent(stateKey, ignored -> new StoreState(storeFolder, storedRulesFile));
+        } catch (IOException e) {
+            throw new StoreInitializationFailedException(e);
+        }
