+            fileNameMode = FileNameMode.RANDOM;
+            ruleViolationFileNameStrategy = description -> UUID.randomUUID().toString();
+        } else if ("description".equals(fileNames)) {
+            fileNameMode = FileNameMode.DESCRIPTION;
+            ruleViolationFileNameStrategy = TextFileBasedViolationStore::createDescriptionBasedFileName;
+        } else {
+            fileNameMode = FileNameMode.CUSTOM;
+            ruleViolationFileNameStrategy = instantiateStrategy(fileNames);
+        }
+    }
