+    private void prepareStore() {
+        Path folder = storeFolder.toPath();
+        Path index = getStoredRulesFile().toPath();
+        boolean indexExists = Files.exists(index, java.nio.file.LinkOption.NOFOLLOW_LINKS);
+
+        if (indexExists) {
+            if (!storeFolder.isDirectory() || !isDirectRegularFile(index)) {
+                throw invalidIndex();
+            }
+            storeState.load();
+            return;
+        }
+
+        if (!storeCreationAllowed) {
+            throw new StoreInitializationFailedException(String.format(
+                    "Creating new violation store is disabled (enable by configuration %s.%s=true)",
+                    ViolationStoreFactory.FREEZE_STORE_PROPERTY_NAME, ALLOW_STORE_CREATION_PROPERTY_NAME));
+        }
+
+        if (integrityMode == IntegrityMode.FAIL) {
+            if (Files.exists(folder, java.nio.file.LinkOption.NOFOLLOW_LINKS) && !storeFolder.isDirectory()) {
+                throw invalidIndex();
+            }
+            List<String> unowned = findUnowned(Collections.<String>emptySet());
+            if (!unowned.isEmpty()) {
+                throw new StoreInitializationFailedException(new IntegrityReport(
+                        Collections.<EntryState>emptyList(), unowned).message());
+            }
+        }
+
+        createFolderAndIndex();
+    }
+
+    private StoreInitializationFailedException invalidIndex() {
+        return new StoreInitializationFailedException(String.format(
+                "The violation store index must be a regular file directly in the store folder: %s",
+                getStoredRulesFile().getAbsolutePath()));
+    }
+
+    private void createFolderAndIndex() {
+        try {
+            Files.createDirectories(storeFolder.toPath());
+            if (!storeFolder.isDirectory()) {
+                throw invalidIndex();
+            }
+            Path index = getStoredRulesFile().toPath();
+            if (Files.exists(index, java.nio.file.LinkOption.NOFOLLOW_LINKS)) {
+                if (!isDirectRegularFile(index)) {
+                    throw invalidIndex();
+                }
+                storeState.load();
+            } else {
+                Files.createFile(index);
+                storeState.setEmpty();
+            }
+        } catch (StoreInitializationFailedException e) {
+            throw e;
+        } catch (IOException e) {
+            throw new StoreInitializationFailedException(e);
+        }
+    }
+
+    private boolean isDirectRegularFile(Path path) {
+        return path.getParent() != null
+                && path.getParent().toAbsolutePath().normalize().equals(storeFolder.toPath().toAbsolutePath().normalize())
+                && Files.isRegularFile(path, java.nio.file.LinkOption.NOFOLLOW_LINKS);
+    }
+
+    private IntegrityReport inspect() {
+        List<EntryState> entries = new ArrayList<>();
+        for (Map.Entry<Object, Object> property : storeState.properties().entrySet()) {
+            String description = ensureUnixLineBreaks(String.valueOf(property.getKey()));
+            String fileName = ensureUnixLineBreaks(String.valueOf(property.getValue()));
+            String derivedName = deriveNameForExistingEntry(fileName, description);
+            entries.add(inspectEntry(description, fileName, derivedName));
+        }
+        markShared(entries);
+
+        Set<String> recordedNames = new HashSet<>();
+        for (EntryState entry : entries) {
+            recordedNames.add(entry.fileName);
+        }
+        List<String> unowned = findUnowned(recordedNames);
+        return new IntegrityReport(entries, unowned);
+    }
+
+    private String deriveNameForExistingEntry(String existingName, String description) {
+        if (fileNameMode == FileNameMode.RANDOM) {
+            // Random names have no repeatable value to compare against. The name in the index is their derivation.
+            return existingName;
+        }
+        return nameFromStrategy(description, true);
+    }
+
+    private EntryState inspectEntry(String description, String fileName, String derivedName) {
+        EntryState result = new EntryState(description, fileName, derivedName);
+        EntryFile entryFile = resolveEntryFile(fileName);
+        result.resolvedPath = entryFile.resolvedPath;
+        result.broken = entryFile.broken;
+        if (!result.broken) {
+            try {
+                result.resolved = readLines(entryFile.resolvedPath).isEmpty();
+            } catch (RuntimeException e) {
+                result.broken = true;
+            }
+        }
+        result.misplaced = !fileName.equals(derivedName);
+        result.colliding = false;
+        result.occupied = result.misplaced && isOccupied(derivedName, fileName);
+        return result;
+    }
+
+    private EntryFile resolveEntryFile(String fileName) {
+        Path folder = storeFolder.toPath().toAbsolutePath().normalize();
+        Path logical;
+        try {
+            logical = folder.resolve(fileName).normalize();
+        } catch (RuntimeException e) {
+            return EntryFile.broken();
+        }
+        if (STORED_RULES_FILE_NAME.equals(fileName)
+                || logical.isAbsolute() && !logical.getParent().equals(folder)
+                || !isDirectName(fileName)
+                || !logical.getParent().equals(folder)) {
+            return EntryFile.broken();
+        }
+
+        try {
+            if (!Files.exists(logical, java.nio.file.LinkOption.NOFOLLOW_LINKS)) {
+                return EntryFile.broken();
+            }
+            Path resolved = logical.toRealPath();
+            boolean regularDirect = resolved.getParent() != null
+                    && resolved.getParent().toAbsolutePath().normalize().equals(folder)
+                    && Files.isRegularFile(resolved, java.nio.file.LinkOption.NOFOLLOW_LINKS);
+            return regularDirect ? EntryFile.of(resolved) : EntryFile.broken(resolved);
+        } catch (IOException e) {
+            return EntryFile.broken();
+        }
+    }
+
+    private boolean isDirectName(String fileName) {
+        try {
+            Path path = new File(fileName).toPath();
+            return !path.isAbsolute() && path.getNameCount() == 1 && !".".equals(fileName) && !"..".equals(fileName);
+        } catch (RuntimeException e) {
+            return false;
+        }
+    }
+
+    private void markShared(List<EntryState> entries) {
+        for (int i = 0; i < entries.size(); i++) {
+            for (int j = i + 1; j < entries.size(); j++) {
+                EntryState first = entries.get(i);
+                EntryState second = entries.get(j);
+                boolean sameName = first.fileName.equals(second.fileName);
+                boolean sameFile = first.resolvedPath != null && second.resolvedPath != null
+                        && first.resolvedPath.equals(second.resolvedPath);
+                if (sameName || sameFile) {
+                    first.shared = true;
+                    second.shared = true;
+                }
+            }
+        }
+
+        Map<String, List<EntryState>> derivedNames = new HashMap<>();
+        for (EntryState entry : entries) {
+            if (!entry.derivedName.equals(entry.fileName) || fileNameMode != FileNameMode.RANDOM) {
+                derivedNames.computeIfAbsent(entry.derivedName, ignored -> new ArrayList<>()).add(entry);
+            }
+        }
+        for (List<EntryState> colliding : derivedNames.values()) {
+            if (colliding.size() > 1) {
+                for (EntryState entry : colliding) {
+                    entry.colliding = true;
+                }
+            }
+        }
+    }
+
+    private boolean isOccupied(String derivedName, String currentName) {
+        if (!isDirectName(derivedName) || STORED_RULES_FILE_NAME.equals(derivedName)) {
+            return true;
+        }
+        if (derivedName.equals(currentName)) {
+            return false;
+        }
+        for (String recordedName : storeState.propertyValues()) {
+            if (derivedName.equals(recordedName)) {
+                return true;
+            }
+        }
+        Path target = storeFolder.toPath().resolve(derivedName);
+        return Files.exists(target, java.nio.file.LinkOption.NOFOLLOW_LINKS);
+    }
+
+    private List<String> findUnowned(Set<String> recordedNames) {
+        if (!Files.exists(storeFolder.toPath(), java.nio.file.LinkOption.NOFOLLOW_LINKS)
+                || !storeFolder.isDirectory()) {
+            return Collections.emptyList();
+        }
+        List<String> result = new ArrayList<>();
+        try (DirectoryStream<Path> children = Files.newDirectoryStream(storeFolder.toPath())) {
+            for (Path child : children) {
+                String name = child.getFileName().toString();
+                if (!STORED_RULES_FILE_NAME.equals(name)
+                        && !recordedNames.contains(name)
+                        && Files.isRegularFile(child, java.nio.file.LinkOption.NOFOLLOW_LINKS)) {
+                    result.add(name);
+                }
+            }
+        } catch (IOException e) {
+            throw new StoreInitializationFailedException(e);
+        }
+        Collections.sort(result);
+        return result;
+    }
+
+    private void repair(IntegrityReport report) {
+        Properties repaired = storeState.copyProperties();
+        boolean changed = false;
+        for (EntryState entry : report.entriesSorted()) {
+            if (entry.shared) {
+                continue;
+            }
+            if (entry.broken) {
+                repaired.remove(entry.description);
+                changed = true;
+            } else if (entry.resolved) {
+                deleteResolvedFile(entry.resolvedPath);
+                repaired.remove(entry.description);
+                changed = true;
+            } else if (entry.misplaced && !entry.colliding && !entry.occupied) {
+                moveResolvedFile(entry.resolvedPath, entry.derivedName);
+                repaired.setProperty(entry.description, entry.derivedName);
+                changed = true;
+            }
+        }
+        if (changed) {
+            storeState.replaceProperties(repaired);
+        }
+    }
+
+    private void deleteResolvedFile(Path path) {
+        if (path == null) {
+            return;
+        }
+        try {
+            Files.delete(path);
+        } catch (IOException e) {
+            throw new StoreInitializationFailedException(e);
+        }
+    }
+
+    private void moveResolvedFile(Path source, String destinationName) {
+        Path destination = directPathForName(destinationName, true);
+        try {
+            Files.move(source, destination);
+        } catch (IOException e) {
+            throw new StoreInitializationFailedException(e);
+        }
+    }
+
+    private String nameFromStrategy(String description, boolean initialization) {
+        String name;
+        try {
+            name = ruleViolationFileNameStrategy.createRuleFileName(description);
+        } catch (RuntimeException e) {
+            if (initialization) {
+                throw new StoreInitializationFailedException(e);
+            }
+            throw e;
+        }
+        if (name == null || name.trim().isEmpty()) {
+            String message = "The rule violation file name strategy returned no name for rule '" + description + "'";
+            if (initialization) {
+                throw new StoreInitializationFailedException(message);
+            }
+            throw new StoreUpdateFailedException(message);
+        }
+        return name;
+    }
+
+    private static String createDescriptionBasedFileName(String description) {
+        Matcher matcher = DESCRIPTION_WORD.matcher(description);
+        String word = matcher.find() ? matcher.group(1) : "rule";
+        return word + "-" + sha256(description);
+    }
+
+    private static String sha256(String value) {
+        try {
+            byte[] digest = MessageDigest.getInstance("SHA-256").digest(value.getBytes(UTF_8));
+            StringBuilder result = new StringBuilder(digest.length * 2);
+            for (byte part : digest) {
+                result.append(String.format("%02x", part & 0xff));
+            }
+            return result.toString();
+        } catch (NoSuchAlgorithmException e) {
+            throw new IllegalStateException(e);
+        }
+    }
+
+    @Override
+    public boolean contains(ArchRule rule) {
+        synchronized (storeState) {
+            return storeState.containsKey(rule.getDescription());
+        }
+    }
+
+    @Override
+    public void save(ArchRule rule, List<String> violations) {
+        log.trace("Storing evaluated rule '{}' with {} violations: {}", rule.getDescription(), violations.size(), violations);
+        synchronized (storeState) {
+            if (!storeUpdateAllowed) {
+                throw new StoreUpdateFailedException(String.format(
+                        "Updating frozen violations is disabled (enable by configuration %s.%s=true)",
+                        ViolationStoreFactory.FREEZE_STORE_PROPERTY_NAME, ALLOW_STORE_UPDATE_PROPERTY_NAME));
+            }
+
+            String description = ensureUnixLineBreaks(rule.getDescription());
+            String existingFileName = storeState.getProperty(description);
+            if (violations.isEmpty() && integrityMode == IntegrityMode.REPAIR) {
+                if (existingFileName == null) {
+                    return;
+                }
+                forgetRule(description, existingFileName);
+                return;
+            }
+
+            String fileName = existingFileName == null ? nameFromStrategy(description, false) : existingFileName;
+            Path target = directPathForName(fileName, false);
+            if (existingFileName == null) {
+                if (storeState.hasValue(fileName) || Files.exists(target, java.nio.file.LinkOption.NOFOLLOW_LINKS)) {
+                    throw new StoreUpdateFailedException("The rule violation file name is already occupied: " + fileName);
+                }
+                writeRuleFile(target, violations, false);
+                Properties updated = storeState.copyProperties();
+                updated.setProperty(description, fileName);
+                try {
+                    storeState.replaceProperties(updated);
+                } catch (RuntimeException e) {
+                    deleteQuietly(target);
+                    throw e;
+                }
+            } else {
+                validateExistingTarget(target, fileName);
+                writeRuleFile(target, violations, true);
+            }
+        }
+    }
+
+    private void forgetRule(String description, String fileName) {
+        EntryFile entryFile = resolveEntryFile(fileName);
+        if (!isSharedWithAnotherEntry(fileName, description)) {
+            if (entryFile.resolvedPath != null) {
+                deleteResolvedFileForUpdate(entryFile.resolvedPath);
+            } else {
+                Path logical = directPathForName(fileName, false);
+                if (Files.exists(logical, java.nio.file.LinkOption.NOFOLLOW_LINKS)) {
+                    deleteResolvedFileForUpdate(logical);
+                }
+            }
+        }
+        Properties updated = storeState.copyProperties();
+        updated.remove(description);
+        storeState.replaceProperties(updated);
